// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Complex64Array } from '@stdlib/types/array';
import { Complex64 } from '@stdlib/types/complex';

/**
* Interface describing `cdotu`.
*/
interface Routine {
	/**
	* Calculates the dot product of vectors `x` and `y`.
	*
	* @param N - number of indexed elements
	* @param x - first input array
	* @param strideX - `x` stride length
	* @param y - second input array
	* @param strideY - `y` stride length
	* @returns dot product
	*
	* @example
	* var Complex64Array = require( '@stdlib/array/complex64' );
	*
	* var x = new Complex64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 7.0 ] );
	* var y = new Complex64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 9.0 ] );
	*
	* var z = cdotu( 3, x, 1, y, 1 );
	* // returns <Complex64>[ -52.0, 82.0 ]
	*/
	( N: number, x: Complex64Array, strideX: number, y: Complex64Array, strideY: number ): Complex64;

	/**
	* Computes the dot product of vectors `x` and `y` using alternative indexing semantics.
	*
	* @param N - number of indexed elements
	* @param x - first input array
	* @param strideX - `x` stride length
	* @param offsetX - starting index for `x`
	* @param y - second input array
	* @param strideY - `y` stride length
	* @param offsetY - starting index for `y`
	* @returns dot product
	*
	* @example
	* var Complex64Array = require( '@stdlib/array/complex64' );
	*
	* var x = new Complex64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 7.0 ] );
	* var y = new Complex64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 9.0 ] );
	*
	* var z = cdotu.ndarray( x.length, x, 1, 0, y, 1, 0 );
	* // returns <Complex64>[ -52.0, 82.0 ]
	*/
	ndarray( N: number, x: Complex64Array, strideX: number, offsetX: number, y: Complex64Array, strideY: number, offsetY: number ): Complex64;
}

/**
* Calculates the dot product of two single-precision complex floating-point vectors.
*
* @param N - number of indexed elements
* @param x - first input array
* @param strideX - `x` stride length
* @param y - second input array
* @param strideY - `y` stride length
* @returns dot product
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
*
* var x = new Complex64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 7.0 ] );
* var y = new Complex64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 9.0 ] );
*
* var z = cdotu( 3, x, 1, y, 1 );
* // returns <Complex64>[ -52.0, 82.0 ]
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
*
* var x = new Complex64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 7.0 ] );
* var y = new Complex64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 9.0 ] );
*
* var z = cdotu.ndarray( x.length, x, 1, 0, y, 1, 0 );
* // returns <Complex64>[ -52.0, 82.0 ]
*/
declare var cdotu: Routine;


// EXPORTS //

export = cdotu;
